RH_HilbertLimit.ActualSpectralCalibration.finite_tail_below_radius.{u_1} {ι : Type u_1}
  (D : RH_HilbertLimit.ActualSpectralCalibration ι) (hR : 1 < RH_HilbertLimit.spectralRadius D.node) :
  ∃ r, 1 < r ∧ r < RH_HilbertLimit.spectralRadius D.node ∧ ∃ s, ∀ i ∉ s, RH_HilbertLimit.ellipseRadius (D.node i) < r

RH_HilbertLimit.ActualSpectralCalibration.spectralRadius_attained.{u_1} {ι : Type u_1}
  (D : RH_HilbertLimit.ActualSpectralCalibration ι) (hR : 1 < RH_HilbertLimit.spectralRadius D.node) :
  ∃ i, RH_HilbertLimit.ellipseRadius (D.node i) = RH_HilbertLimit.spectralRadius D.node

RH_HilbertLimit.iteratedDeriv_conj_of_schwarz {f : ℂ → ℂ}
